components.css:
.ds-event-model { background: var(--model); color: var(--model-ink); margin: 0 -20px; border-radius: 16px; overflow: hidden; padding: 24px 28px 0; border: 1px solid transparent; }
:root[data-theme=light] .ds-event-model { border-color: var(--violet); }
.ds-model-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 24px; font-size: 20px; font-weight: 600; line-height: 1.5; }
.ds-model-heading > span:first-child { color: var(--model-active); }
.ds-model-key { color: var(--model-muted); font-weight: 400; font-size: 16px; }
.ds-model-drawing { margin-top: 24px; }
.ds-model-drawing svg { display: block; width: 100%; height: auto; overflow: visible; }
.ds-model-drawing text { font-family: Manrope, sans-serif; fill: var(--model-ink); }
.ds-node-label { font-size: 20px; letter-spacing: .025em; font-weight: 600; fill: var(--model-muted) !important; }
.ds-node-name { font-size: 28px; letter-spacing: -.02em; font-weight: 500; }
.ds-node-detail { font-size: 20px; fill: var(--model-muted) !important; }
.ds-node-shape { fill: none; stroke: var(--model-line); stroke-width: 1.6; transition: stroke 220ms, fill 220ms; }
.ds-command-shape { stroke: var(--model-active); }
.ds-decision-shape { stroke: var(--model-ink); }
.ds-ledger-frame { fill: var(--model); stroke: var(--model-active); }
.ds-query-shape { fill: var(--query); stroke: var(--model-active); }
.ds-entry-fill { fill: var(--entry); }
.ds-event-index { font-size: 20px; fill: var(--model-muted) !important; }
.ds-event-name { font-family: ui-monospace, SFMono-Regular, Consolas, monospace !important; font-size: 26px; letter-spacing: -.025em; }
.ds-event-check { fill: none; stroke: var(--model-active); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.ds-stock-value { font-size: 55px; fill: var(--model-active) !important; font-variant-numeric: tabular-nums; font-weight: 500; }
.ds-query-name { font-size: 25px; }
.ds-model-connections path { fill: none; stroke: var(--model-active); stroke-width: 1.5; }
.ds-arrow-head { fill: none; stroke: var(--model-active); stroke-width: 1.2; }
.ds-flow-dot { fill: var(--model-ink); stroke: var(--model); stroke-width: 2; opacity: 0; }
.ds-ledger-entry { opacity: 1; transform: translateX(0); transition: opacity 320ms, transform 420ms cubic-bezier(.16, 1, .3, 1); }
.ds-decision-verdict { transition: opacity 200ms; }
[data-stage="0"] .ds-ledger-entry, [data-stage="1"] .ds-ledger-entry, [data-stage="2"] .ds-ledger-entry { opacity: 0; transform: translateX(12px); }
[data-stage="0"] .ds-decision-verdict, [data-stage="1"] .ds-decision-verdict { opacity: 0; }
[data-stage="0"] .ds-query-shape, [data-stage="1"] .ds-query-shape, [data-stage="2"] .ds-query-shape, [data-stage="3"] .ds-query-shape { fill: none; stroke: var(--model-line); }
.ds-ledger-mobile { display: none !important; }
.ds-event-model figcaption { display: flex; align-items: baseline; gap: 8px 12px; flex-wrap: wrap; padding: 24px 4px; border-top: 1px solid var(--model-line); font-size: clamp(20px, 1.85vw, 26px); letter-spacing: -.02em; line-height: 1.5; }
.ds-event-model figcaption strong { font-weight: 600; }
.ds-event-model figcaption span { color: var(--model-muted); }


.ds-event-model{margin:0}.ds-event-model figcaption{margin:0}@media(max-width:1000px){.ds-model-drawing{max-width:380px;margin:24px auto}.ds-ledger-desktop{display:none!important}.ds-ledger-mobile{display:block!important}.ds-ledger-mobile .ds-node-label,.ds-ledger-mobile .ds-node-detail,.ds-ledger-mobile .ds-event-index{font-size:22px}.ds-ledger-mobile .ds-node-name,.ds-ledger-mobile .ds-event-name{font-size:26px}.ds-ledger-mobile .ds-stock-value{font-size:50px}.ds-model-heading{display:block}.ds-model-key{display:block}.ds-event-model figcaption{display:block}}
